// The moderation example's transpile output: developer-owned generated source
// and the tests that drive it. This example exercises deletion (README §12,
// §13; OQ37) — `delete` as a rule effect, `undeletable`, the absorbing
// reference `? initially required`, and the deletion-side exit triggers.
// Regenerated by `gradle generate`.
plugins {
    kotlin("jvm")
}

group = "velle"

repositories {
    mavenCentral()
}

dependencies {
    implementation(project(":compiler"))
    testImplementation(kotlin("test"))
    testImplementation(project(":stores:sqlite"))
}

tasks.test {
    useJUnitPlatform()
}

tasks.register<JavaExec>("generate") {
    description = "Regenerate the Moderation typed surface and executable specs from moderation.velle"
    classpath = sourceSets["main"].runtimeClasspath
    mainClass.set("velle.GenerateKt")
    args("../moderation.velle", "Moderation")
}

kotlin {
    compilerOptions {
        jvmTarget.set(org.jetbrains.kotlin.gradle.dsl.JvmTarget.JVM_21)
    }
}

java {
    sourceCompatibility = JavaVersion.VERSION_21
    targetCompatibility = JavaVersion.VERSION_21
}
